#!/usr/bin/env python3
"""bench_m4/gen_tables.cpp output (stdin) -> audio_tables_arm.inc (stdout)."""
import struct
import sys

wt, win, done = {}, {}, False
for line in sys.stdin:
    f = line.split()
    if not f:
        continue
    if f[0] == "W":
        wt[(int(f[1]), int(f[2]))] = int(f[3], 16)
    elif f[0] == "G":
        win[(int(f[1]), int(f[2]))] = int(f[3])
    elif f[0] == "END":
        done = True
if not done or len(wt) != 7 * 120 or len(win) != 3 * 1000:
    sys.exit("tables_inc.py: incomplete generator output")


def flt(bits):
    v = struct.unpack("<f", struct.pack("<I", bits))[0]
    s = "%.9g" % v
    assert struct.unpack("<I", struct.pack("<f", float(s)))[0] == bits
    if "e" not in s and "." not in s:
        s += ".0"
    return s + "f"


out = ["// Generated by make -C tests audio-tables (tests/bench_m4/gen_tables.cpp,",
       "// tables_inc.py): audio/audio_tables.cpp computeConstTables() run with the",
       "// device toolchain's newlib under QEMU. Do not edit.",
       "const float kWtPitchArm[kWavetableSizes][kPitchTableSize] = {"]
for k in range(7):
    out.append("    {")
    for i in range(0, 120, 6):
        out.append("        " + ", ".join(flt(wt[(k, j)]) for j in range(i, i + 6)) + ",")
    out.append("    },")
out.append("};")
out.append("const uint16_t kWindowArm[3][kGrainWindowLen] = {")
for s in range(3):
    out.append("    {")
    for i in range(0, 1000, 16):
        out.append("        " + ", ".join(str(win[(s, j)]) for j in range(i, min(i + 16, 1000))) + ",")
    out.append("    },")
out.append("};")
print("\n".join(out))
